export type AssistantAttachmentsConfig = {
    status?: string;
};
export type CaptchaProvider = 'turnstile' | 'hcaptcha';
export type CaptchaStatus = 'ENABLED' | 'DISABLED';
export type CaptchaConfig = {
    provider?: CaptchaProvider;
    status?: CaptchaStatus;
};
export type AssistantWidgetConfig = {
    id: string;
    enabled: boolean;
    allowedOrigins: string[];
};
export type AssistantType = {
    askAiOnCodeBlock?: boolean;
    askAiOnTextSelection?: boolean;
    enableAskAiButton?: boolean;
    enableStarterQuestions?: boolean;
    enableContextualStarterQuestions?: boolean;
    enableAskAiSearchBar?: boolean;
    attachments?: AssistantAttachmentsConfig;
    deflection?: {
        enabled?: boolean;
        type?: 'email' | 'link';
        email?: string;
        salesEmail?: string;
        url?: string;
        showHelpButton?: boolean;
        showContactForm?: boolean;
    };
    webSearch?: {
        enabled?: boolean;
        sites?: string[];
    };
    navigation?: {
        enabled?: boolean;
    };
    skills?: {
        enabled?: boolean;
    };
    captcha?: CaptchaConfig;
    widgets?: AssistantWidgetConfig[];
};
